  margin: 0;
}
.results-region {
  margin-top: 30px;
  min-height: 342px;
}
.results-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  min-height: 28px;
  padding-bottom: 16px;
}
.results-heading h2 {
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 500;
  margin: 0;
}
.results-heading > span {
  color: var(--muted);
  font-size: 12px;
}
.results-note {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
  margin: 20px 0 0;
}

.app-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  border-top: 1px solid #1c1920;
  padding: 24px 0;
  color: #9d93a5;
  font-size: 11px;
  line-height: 1.7;
}
.app-footer a {
  text-decoration: none;
}
.app-footer a:hover {
  color: #dfc7f0;
  text-decoration: underline;
  text-underline-offset: 4px;
}

